import{_ as a,o as t,c as o,a0 as i}from"./chunks/framework.K3sFe4KB.js";const u=JSON.parse('{"title":"Reconcile a calendar","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/reconcile-a-calendar.md","filePath":"how-to/reconcile-a-calendar.md"}'),n={name:"how-to/reconcile-a-calendar.md"};function s(d,e,r,c,l,p){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="reconcile-a-calendar" tabindex="-1">Reconcile a calendar <a class="header-anchor" href="#reconcile-a-calendar" aria-label="Permalink to &quot;Reconcile a calendar&quot;">​</a></h1><p>This guide shows you how to drive the plan/apply/drift loop day to day: change events, delete them, recover from crashes, and handle out-of-band edits. It assumes you have a project set up (see <a href="./../tutorials/getting-started.html">Getting started</a>).</p><h2 id="the-everyday-loop" tabindex="-1">The everyday loop <a class="header-anchor" href="#the-everyday-loop" aria-label="Permalink to &quot;The everyday loop&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$EDITOR calendars/work.yaml   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># declare what you want</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cicada</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # catch schema + invariant errors</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cicada</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # preview the diff</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cicada</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # confirm, then reconcile</span></span></code></pre></div><p>Re-running <code>plan</code> after a clean apply reports only <code>noop</code>s — cicada converges, never duplicates.</p><h2 id="change-an-event" tabindex="-1">Change an event <a class="header-anchor" href="#change-an-event" aria-label="Permalink to &quot;Change an event&quot;">​</a></h2><p>Edit the YAML (summary, times, attendees — anything under <code>spec.events[]</code> keeping the same <code>id</code>), then <code>plan</code> and <code>apply</code>. The plan shows an <code>update</code> op with a field-level diff. Changing a recurrence rule produces a <code>replace</code> (delete + recreate), because the instance sets differ.</p><h2 id="delete-an-event" tabindex="-1">Delete an event <a class="header-anchor" href="#delete-an-event" aria-label="Permalink to &quot;Delete an event&quot;">​</a></h2><p>Remove the entry from <code>spec.events[]</code> and apply — cicada generates a <code>delete</code> for any <code>id</code> that is in recorded state but absent from your YAML.</p><p>Cicada <strong>never deletes events it did not create</strong>. The managed set is exactly what recorded state contains; a colleague&#39;s lunch on the same calendar is untouchable, and two cicada projects can share one provider calendar managing disjoint event sets.</p><h2 id="confirm-or-not" tabindex="-1">Confirm, or not <a class="header-anchor" href="#confirm-or-not" aria-label="Permalink to &quot;Confirm, or not&quot;">​</a></h2><p><code>cicada apply</code> prints the plan and prompts <code>[y/N]</code> before writing. Automate with:</p><ul><li><code>--auto-approve</code> — skip the prompt (CI, scripts).</li><li><code>--notify none|externalOnly|all</code> — override the calendar&#39;s <code>spec.apply.sendUpdates</code> for this run. Use <code>none</code> for bulk drift repairs that shouldn&#39;t email the team.</li></ul><h2 id="recover-from-a-crash-mid-apply" tabindex="-1">Recover from a crash mid-apply <a class="header-anchor" href="#recover-from-a-crash-mid-apply" aria-label="Permalink to &quot;Recover from a crash mid-apply&quot;">​</a></h2><p>Apply journals each op into <code>.cicada/state.yaml</code> as it lands. If a run dies partway:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cicada</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --resume</span></span></code></pre></div><p>Already-journaled ops are skipped; for <code>create</code>/<code>replace</code>, cicada also reconciles by the remote <code>cicada:id</code> tag — if the provider write landed but the journal write crashed, the op is recorded as applied instead of duplicated.</p><h2 id="handle-out-of-band-edits" tabindex="-1">Handle out-of-band edits <a class="header-anchor" href="#handle-out-of-band-edits" aria-label="Permalink to &quot;Handle out-of-band edits&quot;">​</a></h2><p><code>cicada drift</code> reports managed events that changed live (<code>modified</code>) or vanished (<code>missing</code>). When apply touches a drifted event it refuses rather than silently overwriting:</p><ul><li><strong>Accept the live edit:</strong> <code>cicada refresh</code> folds live truth into recorded state, then <code>cicada plan</code> + <code>apply</code> to push your YAML back on top — or edit the YAML to match.</li><li><strong>Override it:</strong> <code>cicada apply --force</code> — desired wins; the live edit is overwritten (logged per op).</li></ul><p>A deleted-remotely event resolves the same way: <code>refresh</code> drops the stale record, the next plan proposes <code>create</code>.</p><h2 id="control-notifications" tabindex="-1">Control notifications <a class="header-anchor" href="#control-notifications" aria-label="Permalink to &quot;Control notifications&quot;">​</a></h2><p>Providers email attendees on writes. <code>spec.apply.sendUpdates</code> sets the policy per calendar — <code>none</code>, <code>externalOnly</code> (default), or <code>all</code>. Override per run with <code>apply --notify …</code>.</p>`,23)])])}const y=a(n,[["render",s]]);export{u as __pageData,y as default};
